import{_ as a,o as s,c as o,a2 as n}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Your First Agent","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-agent.md","filePath":"guide/first-agent.md","lastUpdated":1793357966000}'),t={name:"guide/first-agent.md"};function c(d,e,l,r,p,i){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="your-first-agent" tabindex="-1">Your First Agent <a class="header-anchor" href="#your-first-agent" aria-label="Permalink to &quot;Your First Agent&quot;">​</a></h1><p>From an empty folder to an agent that runs, reloads when you edit it and is checked in CI. Each step names the rule that trips people up the first time.</p><h2 id="_1-a-folder-per-agent" tabindex="-1">1. A folder per agent <a class="header-anchor" href="#_1-a-folder-per-agent" aria-label="Permalink to &quot;1. A folder per agent&quot;">​</a></h2><p>A project needs three packages and one provider package (an optional peer of <code>@chamvi/app</code>, install the one your model uses):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/app</span><span style="color:#E7C58C;"> @chamvi/cli</span><span style="color:#E7C58C;"> ai</span><span style="color:#E7C58C;"> @ai-sdk/anthropic</span></span></code></pre></div><p>An agent is a folder below <code>agents/</code> holding an <code>agent.ts</code> that default-exports <code>defineAgent()</code>&#39;s result. The folder name is the agent name, and <code>name</code> must equal it:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// agents/greeter/agent.ts: the folder name is the agent name</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { cron, defineAgent, http } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> default</span><span style="color:#E6DFDE;"> defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;greeter&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // no model: the app&#39;s default (CHAMVI_MODEL)</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Greet whoever sent the payload, in one sentence.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // what starts a run: POST /agents/greeter/runs, and every day at 09:00</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [http.on(), cron.on(</span><span style="color:#E7C58C;">&#39;0 9 * * *&#39;</span><span style="color:#E6DFDE;">)],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>No entry file is needed: without <code>src/index.ts</code>, <code>chamvi</code> runs the default app, <code>createApp({})</code> configured by env alone, with its agents from <code>./agents</code> (or <code>CHAMVI_AGENTS_DIR</code>), and says so on stderr. See <a href="/guide/agent-folders">Agent Folders</a> for imports, prompts and helpers next to <code>agent.ts</code>.</p><h2 id="_2-something-must-start-a-run" tabindex="-1">2. Something must start a run <a class="header-anchor" href="#_2-something-must-start-a-run" aria-label="Permalink to &quot;2. Something must start a run&quot;">​</a></h2><p>An agent without a channel subscription never runs: nothing dispatches it. <code>channels</code> decides what starts one:</p><ul><li><code>http.on()</code>: <code>POST /agents/greeter/runs</code> with <code>{ &quot;payload&quot;: ... }</code> and a bearer token holding <code>agent:greeter:run</code> (and the MCP tool <code>run_greeter</code>). See <a href="/guide/http">HTTP</a>.</li><li><code>cron.on(&#39;0 9 * * *&#39;)</code>: every day at 09:00 in the process&#39;s local zone (or <code>cron.on(expression, { timezone })</code>). See <a href="/guide/scheduler">Scheduler</a>.</li></ul><p>A subscription to a channel no module contributes (a <code>github.on()</code> without <code>githubModule()</code>) is a load issue for a folder agent, so the agent is not registered.</p><h2 id="_3-a-model" tabindex="-1">3. A model <a class="header-anchor" href="#_3-a-model" aria-label="Permalink to &quot;3. A model&quot;">​</a></h2><p>Agents without a <code>model</code> take the app&#39;s default. One provider, one model, in a <code>.env</code> file next to <code>package.json</code>:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;"># .env</span></span>
<span class="line"><span style="color:#E6DFDE;">CHAMVI_MODEL=</span><span style="color:#E7C58C;">anthropic/claude-sonnet-5-5</span></span>
<span class="line"><span style="color:#E6DFDE;">ANTHROPIC_API_KEY=</span><span style="color:#E7C58C;">sk-ant-...</span></span></code></pre></div><p><code>chamvi dev</code> reads <code>.env</code>; <code>chamvi start</code> does not, so in production these come from the process environment (<code>export</code> them in a shell, or the deployment&#39;s env).</p><p>A string names a provider the app declared; nothing falls back to a gateway. See <a href="/guide/models">Pick a Model</a>.</p><h2 id="_4-dev-and-start" tabindex="-1">4. dev and start <a class="header-anchor" href="#_4-dev-and-start" aria-label="Permalink to &quot;4. dev and start&quot;">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npx </span><span style="color:#E7C58C;">chamvi</span><span style="color:#E7C58C;"> dev</span><span style="color:#958A8B;">     # .env loaded, restarts on code changes</span></span>
<span class="line"><span style="color:#E6DFDE;">npx </span><span style="color:#E7C58C;">chamvi</span><span style="color:#E7C58C;"> start</span><span style="color:#958A8B;">   # production: needs CHAMVI_TOKENS</span></span></code></pre></div><p><code>chamvi dev</code> without <code>CHAMVI_TOKENS</code> generates a random token with every permission and logs it once (a warning), so you can call the API right away. <code>chamvi start</code> refuses to start without an authenticator: set <code>CHAMVI_TOKENS</code> to a JSON list, each <code>value</code> at least 16 characters. Generate the value, never copy one from a page:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">export</span><span style="color:#E6DFDE;"> CHAMVI_TOKENS=</span><span style="color:#E7C58C;">&quot;[{ \\&quot;value\\&quot;: \\&quot;</span><span style="color:#E6DFDE;">$(</span><span style="color:#E7C58C;">openssl rand -hex 32</span><span style="color:#E6DFDE;">)</span><span style="color:#E7C58C;">\\&quot;, \\&quot;id\\&quot;: \\&quot;ops\\&quot;, \\&quot;permissions\\&quot;: [\\&quot;*\\&quot;] }]&quot;</span></span></code></pre></div><p>Both listen on port 3000 (<code>PORT</code>). Without <code>DATABASE_URL</code> runs live in memory: a restart loses them (see <a href="/repositories/typeorm">TypeORM store</a> for Postgres).</p><h2 id="_5-the-dashboard" tabindex="-1">5. The dashboard <a class="header-anchor" href="#_5-the-dashboard" aria-label="Permalink to &quot;5. The dashboard&quot;">​</a></h2><p>The default app has no dashboard. Add an entry that includes <code>uiModule()</code> (<code>npm install @chamvi/ui</code>):</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// src/index.ts: the default app plus the dashboard at /ui</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { createApp } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/app&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"><span style="color:#FF7B84;">import</span><span style="color:#E6DFDE;"> { uiModule } </span><span style="color:#FF7B84;">from</span><span style="color:#E7C58C;"> &#39;@chamvi/ui/module&#39;</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">export</span><span style="color:#FF7B84;"> default</span><span style="color:#E6DFDE;"> createApp({ modules: [uiModule()] });</span></span></code></pre></div><p><code>chamvi dev</code> runs <code>src/index.ts</code> directly; for <code>chamvi start</code>, build it first: <code>chamvi build</code> writes <code>dist/index.mjs</code> and needs <code>tsdown</code> (<code>npm install --save-dev tsdown</code>, an optional peer of <code>@chamvi/cli</code>). The dashboard is at <code>/ui</code>; sign in with a token from <code>CHAMVI_TOKENS</code> (or the dev token). See <a href="/guide/ui">Dashboard</a>.</p><h2 id="_6-editing-a-folder-cancels-its-runs" tabindex="-1">6. Editing a folder cancels its runs <a class="header-anchor" href="#_6-editing-a-folder-cancels-its-runs" aria-label="Permalink to &quot;6. Editing a folder cancels its runs&quot;">​</a></h2><p><code>start</code> watches <code>agents/</code>: a changed folder is reloaded within two poll intervals (<code>CHAMVI_AGENTS_POLL_MS</code>, 5 s), and every unsettled run of the agent (<code>queued</code>, <code>running</code>, <code>waiting</code>, <code>interrupted</code>) is cancelled, once across replicas. Each such run stores <code>{ code: &#39;agent_replaced&#39;, message }</code> as its error, and the app logs <code>agent reloaded</code> with the cancelled run ids; deleting the folder does the same with <code>agent_removed</code>.</p><p>Docs and editor leftovers do not count: <code>README*</code>, <code>CHANGELOG*</code>, <code>NOTES*</code>, <code>LICENSE*</code>, <code>*~</code>, <code>*.swp</code>, <code>*.swo</code>, <code>*.bak</code>, <code>*.orig</code>, <code>.DS_Store</code> and dot-files are left out of the folder hash (a <code>.ts</code> or <code>.json</code> always counts). Settle runs waiting for an approval before you edit an agent, and before you upgrade chamvi. A <code>run-job</code> never reloads; see <a href="/guide/agent-folders#jobs-never-reload">Jobs never reload</a>.</p><h2 id="_7-check-it-in-ci" tabindex="-1">7. Check it in CI <a class="header-anchor" href="#_7-check-it-in-ci" aria-label="Permalink to &quot;7. Check it in CI&quot;">​</a></h2><p><code>chamvi start --check</code> runs the start path (config, store connection, model settings, every module, every agent folder with its checks) and exits without starting anything or writing to the store:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npx </span><span style="color:#E7C58C;">chamvi</span><span style="color:#E7C58C;"> build</span><span style="color:#958A8B;">          # only with an entry file (step 5): build exits 2 without one</span></span>
<span class="line"><span style="color:#E6DFDE;">npx </span><span style="color:#E7C58C;">chamvi</span><span style="color:#E7C58C;"> start</span><span style="color:#E7C58C;"> --check</span><span style="color:#958A8B;">  # with the production or staging env</span></span></code></pre></div><p>It needs what a start needs (<code>CHAMVI_TOKENS</code>, the provider keys, <code>DATABASE_URL</code>). It exits 0 with <code>chamvi: start check passed</code>, 2 for a configuration error or an agent folder with a load issue (one per stderr line, never a value), 1 when the store is unreachable or has pending migrations a start would not apply. See <a href="/guide/models#check-before-you-deploy">Check before you deploy</a>.</p>`,33)])])}const g=a(t,[["render",c]]);export{u as __pageData,g as default};
